import { describe, expect, it } from "vitest";
import { parseGcode } from "../gcodeParser";

describe("parseGcode AMS/OrcaSlicer multi-color metadata", () => {
  it("extracts flushedWeightGrams, wipeTowerGrams, and filamentChangeCount from Bambu/Orca headers", () => {
    const gcode = [
      "; generated by BambuStudio 01.09.03.50",
      "; total filament weight [g] : 142.5",
      "; total flushed weight [g] : 34.2",
      "; wipe_tower : 14.8",
      "; total filament changes : 72",
      "G28",
      "G1 X10 Y10 E5",
    ].join("\n");

    const parsed = parseGcode(gcode);
    expect(parsed.flushedWeightGrams).toBe(34.2);
    expect(parsed.wipeTowerGrams).toBe(14.8);
    expect(parsed.filamentChangeCount).toBe(72);
  });

  it("extracts alternative OrcaSlicer/PrusaSlicer key variants", () => {
    const gcode = [
      "; filament_flushed [g] = 19.4",
      "; wipe tower used [g] = 8.5",
      "; filament_changes = 41",
    ].join("\n");

    const parsed = parseGcode(gcode);
    expect(parsed.flushedWeightGrams).toBe(19.4);
    expect(parsed.wipeTowerGrams).toBe(8.5);
    expect(parsed.filamentChangeCount).toBe(41);
  });

  it("leaves AMS fields undefined when no multi-color metadata is present", () => {
    const gcode = ["; generated by PrusaSlicer", "G28", "G1 X5 Y5 E2"].join("\n");
    const parsed = parseGcode(gcode);
    expect(parsed.flushedWeightGrams).toBeUndefined();
    expect(parsed.wipeTowerGrams).toBeUndefined();
    expect(parsed.filamentChangeCount).toBeUndefined();
  });
});
